22	const PROCESSING_FEE = 5;
23	const FIRST_INSURANCE_SURCHARGE = 0.1;
24	
25	/** Premiums round up — in the MHPCO's favour. Float noise is discarded first. */
26	const roundUpToWholeG = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
27	
28	/** The item types the MHPCO will insure, and what each costs to cover. */
29	const BASE_PREMIUMS = {
30	  sword: 100,
31	  amulet: 60,
32	  staff: 80,
33	  potion: 40,
34	} as const satisfies Record<string, number>;
35	
36	type InsurableType = keyof typeof BASE_PREMIUMS;
37	
38	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type as InsurableType];
39	
40	const quotePremium = (items: Item[]): number => {
41	  const policyBase = items.reduce((sum, item) => sum + basePremiumOf(item), 0);
42	  const withFirstInsurance = policyBase * (1 + FIRST_INSURANCE_SURCHARGE);
43	  const withProcessingFee = withFirstInsurance + PROCESSING_FEE;
44	  return roundUpToWholeG(withProcessingFee);
45	};
46	
47	export const runScenario = (scenario: Scenario): ScenarioResult => {
48	  return { results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })) };
49	};
